    12	@Service
    13	public class OrderSummaryCalculator {
    14	
    15	    private final ProductService productService;
    16	    private final TransLogService transLogService;
    17	
    18	    public OrderSummaryCalculator(ProductService productService, TransLogService transLogService) {
    19	        this.productService = productService;
    20	        this.transLogService = transLogService;
    21	    }
    22	
    23	    public OrderSummary calculate(CheckoutRequestDto request) {
    24	        BigDecimal productsSubtotal = calculateProductsSubtotal(request);
    25	        BigDecimal shippingCost = BigDecimal.ZERO;
    26	        Integer deliveryDays = 0;
    27	
    28	        ShippingMethod shippingMethod = ShippingMethod.valueOf(request.getShippingMethod());
    29	        Region region = Region.valueOf(request.getRegion());
    30	        ClubTier clubTier = ClubTier.valueOf(request.getClubTier());
    31	
    32	        if (clubTier == ClubTier.GOLD && shippingMethod != ShippingMethod.COURIER && shippingMethod != ShippingMethod.STORE_PICKUP) {
    33	            shippingCost = BigDecimal.ZERO;
    34	            ShippingQuote quote = getShippingQuote(request, shippingMethod, BigDecimal.ZERO, region);
    35	            if (quote != null) {
    36	                deliveryDays = quote.days;
    37	            }
    38	        } else {
    39	            ShippingQuote quote = getShippingQuote(request, shippingMethod, BigDecimal.ZERO, region);
    40	            if (quote != null) {
    41	                shippingCost = quote.cost;
    42	                deliveryDays = quote.days;
    43	            }
    44	        }
    45	
    46	        BigDecimal couponDiscount = calculateCouponDiscount(request, productsSubtotal, shippingCost, shippingMethod);
    47	        BigDecimal insurance = calculateInsurance(productsSubtotal, region);
    48	        BigDecimal subtotalBeforePayment = productsSubtotal
    49	                .subtract(couponDiscount)
    50	                .add(shippingCost)
    51	                .add(insurance);
    52	
    53	        BigDecimal paymentAdjustment = calculatePaymentAdjustment(request, subtotalBeforePayment);
    54	        BigDecimal finalTotal = subtotalBeforePayment.add(paymentAdjustment);
    55	
    56	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
    57	        BigDecimal installmentAmount = calculateInstallmentAmount(finalTotal, request.getPaymentMethod(), installments);
    58	
    59	        BigDecimal nextPurchaseCredit = calculateClubCredit(productsSubtotal, clubTier);
    60	        Boolean gift = shouldGift(productsSubtotal, clubTier);
    61	
    62	        return new OrderSummary(
    63	                round(productsSubtotal),
    64	                round(couponDiscount),
    65	                round(shippingCost),
    66	                deliveryDays,
    67	                round(insurance),
    68	                round(paymentAdjustment),
    69	                round(finalTotal),
    70	                installments,
    71	                round(installmentAmount),
    72	                round(nextPurchaseCredit),
    73	                gift
    74	        );
    75	    }
    76	
    77	    public BigDecimal calculateProductsSubtotal(CheckoutRequestDto request) {
    78	        BigDecimal subtotal = BigDecimal.ZERO;
    79	        for (var item : request.getItems()) {
    80	            Product product = productService.getProduct(item.getSku());
    81	            BigDecimal itemTotal = product.getPrice().multiply(new BigDecimal(item.getQuantity()));
    82	            subtotal = subtotal.add(itemTotal);
    83	        }
    84	        return subtotal;
    85	    }
    86	
    87	    private BigDecimal calculateCouponDiscount(CheckoutRequestDto request, BigDecimal productsSubtotal, BigDecimal shippingCost, ShippingMethod shippingMethod) {
    88	        if (request.getCoupon() == null || request.getCoupon().isEmpty()) {
    89	            return BigDecimal.ZERO;
    90	        }
    91	
    92	        CouponCode coupon = CouponCode.valueOf(request.getCoupon());
    93	        BigDecimal discount = BigDecimal.ZERO;
    94	
    95	        switch (coupon) {
    96	            case WELCOME10:
    97	                discount = productsSubtotal.multiply(new BigDecimal("0.10"));
    98	                break;
    99	            case MINUS50:
   100	                if (productsSubtotal.compareTo(new BigDecimal("300")) >= 0) {
   101	                    discount = new BigDecimal("50");
   102	                }
   103	                break;
   104	            case FREESHIPPING:
   105	                if (shippingMethod != ShippingMethod.STORE_PICKUP) {
   106	                    discount = shippingCost;
   107	                }
   108	                break;
   109	            case BUY3PAY2:
   110	                discount = calculateBuy3Pay2Discount(request, productsSubtotal);
   111	                break;
   112	        }
   113	
   114	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"));
   115	        if (discount.compareTo(maxDiscount) > 0) {
   116	            discount = maxDiscount;
   117	        }
   118	
   119	        return discount;
   120	    }
   121	
   122	    private BigDecimal calculateBuy3Pay2Discount(CheckoutRequestDto request, BigDecimal productsSubtotal) {
   123	        BigDecimal discount = BigDecimal.ZERO;
   124	
   125	        Map<String, Integer> skuQuantities = new HashMap<>();
   126	        for (var item : request.getItems()) {
   127	            skuQuantities.put(item.getSku(), item.getQuantity());
   128	        }
   129	
   130	        for (var entry : skuQuantities.entrySet()) {
   131	            int quantity = entry.getValue();
   132	            int freeUnits = quantity / 3;
   133	            if (freeUnits > 0) {
   134	                Product product = productService.getProduct(entry.getKey());
   135	                discount = discount.add(product.getPrice().multiply(new BigDecimal(freeUnits)));
   136	            }
   137	        }
   138	
   139	        return discount;
   140	    }
   141	
   142	    private ShippingQuote getShippingQuote(CheckoutRequestDto request, ShippingMethod method, BigDecimal currentCost, Region region) {
   143	        ShippingQuote baseQuote = null;
   144	
   145	        switch (method) {
   146	            case ECONOMY:
   147	            case EXPRESS:
   148	                baseQuote = transLogService.getQuote(request.getZipCode(), calculateTotalWeight(request), method);
   149	                break;
   150	            case STORE_PICKUP:
   151	                baseQuote = new ShippingQuote(BigDecimal.ZERO, 1);
   152	                break;
   153	            case COURIER:
   154	                BigDecimal totalWeight = calculateTotalWeight(request);
   155	                if (totalWeight.compareTo(new BigDecimal("5")) > 0) {
   156	                    return null;
   157	                }
   158	                baseQuote = new ShippingQuote(new BigDecimal("18"), 0);
   159	                break;
   160	            default:
   161	                return null;
   162	        }
   163	
   164	        if (baseQuote != null) {
   165	            int adjustedDays = calculateDeliveryDays(method, region, baseQuote.days);
   166	            return new ShippingQuote(baseQuote.cost, adjustedDays);
   167	        }
   168	
   169	        return baseQuote;
   170	    }
   171	
   172	    private Integer calculateDeliveryDays(ShippingMethod method, Region region, int baseDeliveryDays) {
   173	        int days = baseDeliveryDays;
   174	
   175	        if (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS) {
   176	            if (region == Region.NORTH) {
   177	                days += 3;
   178	            } else if (region == Region.NORTHEAST) {
   179	                days += 2;
   180	            }
   181	        }
   182	
   183	        return days;
   184	    }
   185	
   186	    private BigDecimal calculateTotalWeight(CheckoutRequestDto request) {
   187	        BigDecimal totalWeight = BigDecimal.ZERO;
   188	        for (var item : request.getItems()) {
   189	            Product product = productService.getProduct(item.getSku());
   190	            BigDecimal itemWeight = product.getWeightKg().multiply(new BigDecimal(item.getQuantity()));
   191	            totalWeight = totalWeight.add(itemWeight);
   192	        }
   193	        return totalWeight;
   194	    }
   195	
   196	    private BigDecimal calculateInsurance(BigDecimal productsSubtotal, Region region) {
   197	        BigDecimal percentage;
   198	        BigDecimal limit;
   199	
   200	        switch (region) {
   201	            case SOUTHEAST, SOUTH:
   202	                percentage = new BigDecimal("0.01");
   203	                limit = null;
   204	                break;
   205	            case MIDWEST:
   206	                percentage = new BigDecimal("0.015");
   207	                limit = null;
   208	                break;
   209	            case NORTH:
   210	                percentage = new BigDecimal("0.025");
   211	                limit = new BigDecimal("30");
   212	                break;
   213	            case NORTHEAST:
   214	                percentage = new BigDecimal("0.02");
   215	                limit = new BigDecimal("30");
   216	                break;
   217	            default:
   218	                return BigDecimal.ZERO;
   219	        }
   220	
   221	        BigDecimal insurance = productsSubtotal.multiply(percentage);
   222	        if (limit != null && insurance.compareTo(limit) > 0) {
   223	            insurance = limit;
   224	        }
   225	
   226	        return insurance;
   227	    }
   228	
   229	    private BigDecimal calculatePaymentAdjustment(CheckoutRequestDto request, BigDecimal subtotal) {
   230	        PaymentMethod method = PaymentMethod.valueOf(request.getPaymentMethod());
   231	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
   232	
   233	        switch (method) {
   234	            case PIX:
   235	                if (request.getCoupon() == null || request.getCoupon().isEmpty()) {
   236	                    return subtotal.multiply(new BigDecimal("0.05")).negate();
   237	                }
   238	                return BigDecimal.ZERO;
   239	            case CREDIT_CARD:
   240	                if (installments <= 3) {
   241	                    return BigDecimal.ZERO;
   242	                }
   243	                return calculateCreditCardInterest(subtotal, installments);
   244	            case BANK_SLIP:
   245	                return new BigDecimal("3.49");
   246	            default:
   247	                return BigDecimal.ZERO;
   248	        }
   249	    }
   250	
   251	    private BigDecimal calculateCreditCardInterest(BigDecimal total, Integer installments) {
   252	        BigDecimal monthlyRate = new BigDecimal("0.0199");
   253	        BigDecimal installmentAmount = total
   254	                .multiply(monthlyRate)
   255	                .divide(
   256	                        BigDecimal.ONE.subtract(
   257	                                BigDecimal.ONE.add(monthlyRate).pow(-installments)
   258	                        ),
   259	                        10,
   260	                        RoundingMode.HALF_EVEN
   261	                );
   262	
   263	        BigDecimal totalWithInterest = installmentAmount.multiply(new BigDecimal(installments));
   264	        return totalWithInterest.subtract(total);
   265	    }
   266	
   267	    private BigDecimal calculateInstallmentAmount(BigDecimal finalTotal, String paymentMethod, Integer installments) {
   268	        PaymentMethod method = PaymentMethod.valueOf(paymentMethod);
   269	
   270	        if (method == PaymentMethod.CREDIT_CARD && installments > 3) {
   271	            BigDecimal monthlyRate = new BigDecimal("0.0199");
   272	            return finalTotal
   273	                    .multiply(monthlyRate)
   274	                    .divide(
   275	                            BigDecimal.ONE.subtract(
   276	                                    BigDecimal.ONE.add(monthlyRate).pow(-installments)
   277	                            ),
   278	                            2,
   279	                            RoundingMode.HALF_EVEN
   280	                    );
   281	        }
   282	
   283	        return finalTotal.divide(new BigDecimal(installments), 2, RoundingMode.HALF_EVEN);
   284	    }
   285	
   286	    private BigDecimal calculateClubCredit(BigDecimal productsSubtotal, ClubTier tier) {
   287	        switch (tier) {
   288	            case SILVER:
   289	                return productsSubtotal.multiply(new BigDecimal("0.02"));
   290	            case GOLD:
   291	                return productsSubtotal.multiply(new BigDecimal("0.05"));
   292	            default:
   293	                return BigDecimal.ZERO;
   294	        }
   295	    }
   296	
   297	    private Boolean shouldGift(BigDecimal productsSubtotal, ClubTier tier) {
   298	        if (tier == ClubTier.GOLD && productsSubtotal.compareTo(new BigDecimal("500")) > 0) {
   299	            return true;
   300	        }
   301	        return false;
   302	    }
   303	
   304	    private BigDecimal round(BigDecimal value) {
   305	        return value.setScale(2, RoundingMode.HALF_EVEN);
   306	    }
   307	
   308	    public static class ShippingQuote {
   309	        public BigDecimal cost;
   310	        public Integer days;
   311	
   312	        public ShippingQuote(BigDecimal cost, Integer days) {
   313	            this.cost = cost;
   314	            this.days = days;
   315	        }
   316	    }
   317	}
