    29	    public OrderSummaryCalculator.ShippingQuote getQuote(String zipCode, BigDecimal weightKg, ShippingMethod method) {
    30	        try {
    31	            String service = method == ShippingMethod.ECONOMY ? "STD" : "EXP";
    32	            long weightGrams = Math.round(weightKg.doubleValue() * 1000);
    33	
    34	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    35	                    translogUrl, zipCode, weightGrams, service);
    36	
