    16	
    17	@Service
    18	public class TransLogService {
    19	
    20	    @Value("${translog.url:http://localhost:9999}")
    21	    private String translogUrl;
    22	
    23	    private final HttpClient httpClient = HttpClient.newBuilder()
    24	            .connectTimeout(java.time.Duration.ofSeconds(2))
    25	            .build();
    26	
    27	    private final ObjectMapper objectMapper = new ObjectMapper();
    28	
    29	    public OrderSummaryCalculator.ShippingQuote getQuote(String zipCode, BigDecimal weightKg, ShippingMethod method) {
    30	        try {
    31	            String service = method == ShippingMethod.ECONOMY ? "STD" : "EXP";
    32	            long weightGrams = Math.round(weightKg.doubleValue() * 1000);
    33	
    34	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    35	                    translogUrl, zipCode, weightGrams, service);
    36	
    37	            HttpRequest request = HttpRequest.newBuilder()
    38	                    .uri(URI.create(url))
    39	                    .timeout(java.time.Duration.ofSeconds(2))
    40	                    .GET()
    41	                    .build();
    42	
    43	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    44	
    45	            if (response.statusCode() != 200) {
    46	                return null;
    47	            }
    48	
    49	            @SuppressWarnings("unchecked")
    50	            Map<String, Object> responseBody = objectMapper.readValue(response.body(), Map.class);
    51	
    52	            if (responseBody.containsKey("error")) {
    53	                return null;
    54	            }
    55	
    56	            int priceCents = ((Number) responseBody.get("price_cents")).intValue();
    57	            int etaHours = ((Number) responseBody.get("eta_hours")).intValue();
    58	
    59	            BigDecimal price = new BigDecimal(priceCents).divide(new BigDecimal(100));
    60	            int days = (int) Math.ceil((double) etaHours / 24);
    61	
    62	            return new OrderSummaryCalculator.ShippingQuote(price, days);
    63	        } catch (IOException | InterruptedException e) {
    64	            return null;
    65	        }
    66	    }
    67	}

